package basic_program;

public class DataType {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
       System.out.println("Max size of Byte :" + Byte.MAX_VALUE);
       System.out.println("Min size of Byte :" + Byte.MIN_VALUE);
       System.out.println("Max size of Short :" + Short.MAX_VALUE);
       System.out.println("Min size of Short :" + Short.MIN_VALUE);
       System.out.println("Max size of Int :" + Integer.MAX_VALUE);
       System.out.println("Min size of Int :" + Integer.MIN_VALUE);
       System.out.println("Max size of long :" + Long.MAX_VALUE);
       System.out.println("Min size of long :" + Long.MIN_VALUE);
       System.out.println("Max size of float :" + Float.MAX_VALUE);
       System.out.println("Min size of float :" + Float.MIN_VALUE);
       System.out.println("Max size of Double :" + Double.MAX_VALUE);
       System.out.println("Min size of Double :" + Double.MIN_VALUE);
       System.out.println("Max size of Char :" + Character.MAX_VALUE);
       System.out.println("Min size of Char :" + Character.MIN_VALUE);
       
	}

}
